+import * as fs from "fs";
+import * as path from "path";
+
+export interface CachedRecord {
+  repoName: string;
+  recordId: string;
+  sha: string;
+  path: string;
+  trailer: string;
+  timestamp: number;
+}
+
+export interface CacheIndex {
+  repos: Record<string, { lastSync: number; recordCount: number }>;
+}
+
+export class OrgCache {
+  private cacheDir: string;
+  private indexFile: string;
+  private cacheFile: string;
+
+  constructor(customCacheDir?: string) {
+    this.cacheDir =
+      customCacheDir || path.join(process.env.HOME || "/tmp", ".commitlore-cache");
+    this.indexFile = path.join(this.cacheDir, "index.json");
+    this.cacheFile = path.join(this.cacheDir, "records.jsonl");
+    this.ensureDir();
+  }
+
+  private ensureDir(): void {
+    if (!fs.existsSync(this.cacheDir)) {
+      fs.mkdirSync(this.cacheDir, { recursive: true });
+    }
+  }
+
+  getIndex(): CacheIndex {
+    if (!fs.existsSync(this.indexFile)) {
+      return { repos: {} };
+    }
+    return JSON.parse(fs.readFileSync(this.indexFile, "utf-8"));
+  }
+
+  addRecords(repoName: string, records: Omit<CachedRecord, "repoName">[]): void {
+    const timestamp = Date.now();
+    const recordsToAdd = records.map((r) => ({ ...r, repoName }));
+
+    // Append to JSONL file
+    const stream = fs.createWriteStream(this.cacheFile, { flags: "a" });
+    for (const record of recordsToAdd) {
+      stream.write(JSON.stringify(record) + "\n");
+    }
+    stream.end();
+
+    // Update index
+    const index = this.getIndex();
+    index.repos[repoName] = {
+      lastSync: timestamp,
+      recordCount: records.length,
+    };
+    fs.writeFileSync(this.indexFile, JSON.stringify(index, null, 2));
+  }
+
+  queryAll(predicate?: (record: CachedRecord) => boolean): CachedRecord[] {
+    if (!fs.existsSync(this.cacheFile)) {
+      return [];
+    }
+
+    const lines = fs.readFileSync(this.cacheFile, "utf-8").trim().split("\n");
+    const records = lines
+      .filter((line) => line.length > 0)
+      .map((line) => JSON.parse(line) as CachedRecord);
+
+    return predicate ? records.filter(predicate) : records;
+  }
+
+  searchByKeyword(keyword: string): CachedRecord[] {
+    const lowerKeyword = keyword.toLowerCase();
+    return this.queryAll((r) =>
+      r.trailer.toLowerCase().includes(lowerKeyword) ||
+      r.recordId.toLowerCase().includes(lowerKeyword)
+    );
+  }
+
+  getRepoRecords(repoName: string): CachedRecord[] {
+    return this.queryAll((r) => r.repoName === repoName);
+  }
+
+  clear(): void {
+    if (fs.existsSync(this.cacheFile)) {
+      fs.unlinkSync(this.cacheFile);
+    }
+    if (fs.existsSync(this.indexFile)) {
+      fs.unlinkSync(this.indexFile);
+    }
+  }
+
+  getCacheStatus(): Record<string, { lastSync: number; age: string; recordCount: number }> {
+    const index = this.getIndex();
+    const now = Date.now();
+    return Object.fromEntries(
+      Object.entries(index.repos).map(([repo, info]) => [
+        repo,
+        {
+          lastSync: info.lastSync,
+          age: this.formatAge(now - info.lastSync),
+          recordCount: info.recordCount,
+        },
+      ])
+    );
+  }
+
+  private formatAge(ms: number): string {
+    const seconds = Math.floor(ms / 1000);
+    if (seconds < 60) return `${seconds}s ago`;
+    const minutes = Math.floor(seconds / 60);
+    if (minutes < 60) return `${minutes}m ago`;
+    const hours = Math.floor(minutes / 60);
+    if (hours < 24) return `${hours}h ago`;
+    const days = Math.floor(hours / 24);
+    return `${days}d ago`;
+  }
+}
