@@ -0,0 +1,233 @@
+import * as fs from "fs";
+import * as path from "path";
+import { OrgCache } from "./cache";
+import { OrgQueryEngine } from "./query";
+import { OrgSyncer, RemoteRepo } from "./syncer";
+
+interface RepoConfig {
+  repos: RemoteRepo[];
+}
+
+export class OrgCLI {
+  private cache: OrgCache;
+  private syncer: OrgSyncer;
+  private queryEngine: OrgQueryEngine;
+  private configFile: string;
+
+  constructor(customCacheDir?: string) {
+    this.cache = new OrgCache(customCacheDir);
+    this.syncer = new OrgSyncer(this.cache);
+    this.queryEngine = new OrgQueryEngine(this.cache);
+    this.configFile = path.join(
+      customCacheDir || path.join(process.env.HOME || "/tmp", ".commitlore-cache"),
+      "repos.json"
+    );
+  }
+
+  loadConfig(): RepoConfig {
+    if (!fs.existsSync(this.configFile)) {
+      return { repos: [] };
+    }
+    return JSON.parse(fs.readFileSync(this.configFile, "utf-8"));
+  }
+
+  saveConfig(config: RepoConfig): void {
+    const dir = path.dirname(this.configFile);
+    if (!fs.existsSync(dir)) {
+      fs.mkdirSync(dir, { recursive: true });
+    }
+    fs.writeFileSync(this.configFile, JSON.stringify(config, null, 2));
+  }
+
+  async syncCommand(repoNames?: string[]): Promise<void> {
+    const config = this.loadConfig();
+
+    let repos = config.repos;
+    if (repoNames && repoNames.length > 0) {
+      repos = repos.filter((r) => repoNames.includes(r.name));
+    }
+
+    if (repos.length === 0) {
+      console.log("No repos configured. Use 'commitlore-org add-repo' to add repositories.");
+      return;
+    }
+
+    this.syncer.syncMultiple(repos);
+  }
+
+  addRepoCommand(name: string, url: string): void {
+    const config = this.loadConfig();
+    const exists = config.repos.some((r) => r.name === name);
+
+    if (exists) {
+      console.log(`Repository '${name}' already exists.`);
+      return;
+    }
+
+    config.repos.push({ name, url });
+    this.saveConfig(config);
+    console.log(`✓ Added repository '${name}' (${url})`);
+  }
+
+  listReposCommand(): void {
+    const config = this.loadConfig();
+    const status = this.cache.getCacheStatus();
+
+    if (config.repos.length === 0) {
+      console.log("No repositories configured.");
+      return;
+    }
+
+    console.log("Configured repositories:\n");
+    for (const repo of config.repos) {
+      const info = status[repo.name];
+      if (info) {
+        console.log(`  ${repo.name} (${info.recordCount} records, synced ${info.age})`);
+      } else {
+        console.log(`  ${repo.name} (never synced)`);
+      }
+      console.log(`    URL: ${repo.url}`);
+    }
+  }
+
+  queryCommand(options: {
+    keyword?: string;
+    recordId?: string;
+    repo?: string;
+    json?: boolean;
+  }): void {
+    const result = this.queryEngine.query({
+      keyword: options.keyword,
+      recordId: options.recordId,
+      repo: options.repo,
+      limit: 100,
+    });
+
+    if (options.json) {
+      console.log(JSON.stringify(result.records, null, 2));
+    } else {
+      this.printResults(result.records);
+    }
+
+    if (result.total === 0) {
+      console.log("No results found.");
+    } else {
+      console.log(
+        `\n${result.total} results across ${result.repos.size} ${
+          result.repos.size === 1 ? "repo" : "repos"
+        }`
+      );
+    }
+  }
+
+  ruledOutCommand(topic: string): void {
+    const result = this.queryEngine.findRuledOut(topic);
+
+    console.log(`\nRuled out decisions about "${topic}":\n`);
+    this.printResults(result.records);
+
+    if (result.total === 0) {
+      console.log("No ruled-out decisions found.");
+    } else {
+      console.log(`\n${result.total} ruled-out decisions across ${result.repos.size} repos`);
+    }
+  }
+
+  statusCommand(): void {
+    const status = this.cache.getCacheStatus();
+
+    if (Object.keys(status).length === 0) {
+      console.log("Cache is empty. Run 'commitlore-org sync' to populate it.");
+      return;
+    }
+
+    console.log("Cache status:\n");
+    let totalRecords = 0;
+    for (const [repo, info] of Object.entries(status)) {
+      console.log(`  ${repo}: ${info.recordCount} records (${info.age})`);
+      totalRecords += info.recordCount;
+    }
+    console.log(`\nTotal: ${totalRecords} records`);
+  }
+
+  clearCacheCommand(confirm: boolean = false): void {
+    if (!confirm) {
+      console.log("Warning: This will delete all cached records.");
+      console.log("Re-run with --yes to confirm.");
+      return;
+    }
+
+    this.cache.clear();
+    console.log("✓ Cache cleared");
+  }
+
+  private printResults(records: any[]): void {
+    for (const record of records) {
+      console.log(`${record.repoName}:${record.sha.substring(0, 8)}`);
+      console.log(`  Record-ID: ${record.recordId}`);
+      console.log(`  ${record.trailer}`);
+      console.log();
+    }
+  }
+}
+
+// CLI entry point
+async function main() {
+  const args = process.argv.slice(2);
+  const command = args[0];
+
+  const cli = new OrgCLI();
+
+  switch (command) {
+    case "sync":
+      await cli.syncCommand(args.slice(1));
+      break;
+    case "add-repo":
+      if (args.length < 3) {
+        console.error("Usage: commitlore-org add-repo <name> <url>");
+        process.exit(1);
+      }
+      cli.addRepoCommand(args[1], args[2]);
+      break;
+    case "list-repos":
+      cli.listReposCommand();
+      break;
+    case "query":
+      cli.queryCommand({
+        keyword: args.includes("--keyword") ? args[args.indexOf("--keyword") + 1] : undefined,
+        recordId: args.includes("--id") ? args[args.indexOf("--id") + 1] : undefined,
+        repo: args.includes("--repo") ? args[args.indexOf("--repo") + 1] : undefined,
+        json: args.includes("--json"),
+      });
+      break;
+    case "ruled-out":
+      if (args.length < 2) {
+        console.error("Usage: commitlore-org ruled-out <topic>");
+        process.exit(1);
+      }
+      cli.ruledOutCommand(args.slice(1).join(" "));
+      break;
+    case "status":
+      cli.statusCommand();
+      break;
+    case "clear-cache":
+      cli.clearCacheCommand(args.includes("--yes"));
+      break;
+    default:
+      console.error(`Unknown command: ${command}`);
+      console.error("\nUsage:");
+      console.error("  commitlore-org sync [repos...]        Sync configured repos");
+      console.error("  commitlore-org add-repo <name> <url>  Add a repository");
+      console.error("  commitlore-org list-repos             List configured repos");
+      console.error("  commitlore-org query [options]        Query cached records");
+      console.error("  commitlore-org ruled-out <topic>      Find ruled-out decisions");
+      console.error("  commitlore-org status                 Show cache status");
+      process.exit(1);
+  }
+}
+
+if (require.main === module) {
+  main().catch(console.error);
+}
+
+export { OrgCLI };
