+import { OrgCache, CachedRecord } from "./cache";
+
+export interface QueryOptions {
+  repo?: string; // Filter by repo
+  keyword?: string;
+  recordId?: string;
+  limit?: number;
+}
+
+export interface QueryResult {
+  records: CachedRecord[];
+  total: number;
+  repos: Set<string>;
+}
+
+export class OrgQueryEngine {
+  private cache: OrgCache;
+
+  constructor(cache: OrgCache) {
+    this.cache = cache;
+  }
+
+  query(options: QueryOptions): QueryResult {
+    let results = this.cache.queryAll();
+
+    // Filter by repo
+    if (options.repo) {
+      results = results.filter((r) => r.repoName === options.repo);
+    }
+
+    // Filter by keyword
+    if (options.keyword) {
+      const lowerKeyword = options.keyword.toLowerCase();
+      results = results.filter(
+        (r) =>
+          r.trailer.toLowerCase().includes(lowerKeyword) ||
+          r.recordId.toLowerCase().includes(lowerKeyword) ||
+          r.repoName.toLowerCase().includes(lowerKeyword)
+      );
+    }
+
+    // Filter by record ID
+    if (options.recordId) {
+      results = results.filter((r) => r.recordId === options.recordId);
+    }
+
+    // Apply limit
+    if (options.limit) {
+      results = results.slice(0, options.limit);
+    }
+
+    return {
+      records: results,
+      total: results.length,
+      repos: new Set(results.map((r) => r.repoName)),
+    };
+  }
+
+  findRuledOut(topic: string): QueryResult {
+    return this.query({
+      keyword: `ruled out ${topic}`,
+      limit: 1000,
+    });
+  }
+
+  findWarnings(topic?: string): QueryResult {
+    return this.query({
+      keyword: topic ? `warn ${topic}` : "warn",
+      limit: 1000,
+    });
+  }
+
+  findLimits(topic?: string): QueryResult {
+    return this.query({
+      keyword: topic ? `limit ${topic}` : "limit",
+      limit: 1000,
+    });
+  }
+
+  groupByRecord(): Record<string, CachedRecord[]> {
+    const all = this.cache.queryAll();
+    const grouped: Record<string, CachedRecord[]> = {};
+    for (const record of all) {
+      if (!grouped[record.recordId]) {
+        grouped[record.recordId] = [];
+      }
+      grouped[record.recordId].push(record);
+    }
+    return grouped;
+  }
+
+  findInvolving(term: string, options?: { type?: "rule" | "limit" | "warn" }): QueryResult {
+    let results = this.cache.queryAll();
+
+    results = results.filter((r) => r.trailer.toLowerCase().includes(term.toLowerCase()));
+
+    if (options?.type) {
+      results = results.filter((r) =>
+        r.trailer.toLowerCase().startsWith(options.type + " ")
+      );
+    }
+
+    return {
+      records: results,
+      total: results.length,
+      repos: new Set(results.map((r) => r.repoName)),
+    };
+  }
+}
