+import { execSync } from "child_process";
+import { OrgCache } from "./cache";
+
+export interface RemoteRepo {
+  name: string;
+  url: string; // GitHub URL or git repo URL
+}
+
+export interface RecordRow {
+  recordId: string;
+  sha: string;
+  path: string;
+  trailer: string;
+}
+
+export class OrgSyncer {
+  private cache: OrgCache;
+
+  constructor(cache: OrgCache) {
+    this.cache = cache;
+  }
+
+  syncRepo(repo: RemoteRepo): { synced: number; errors: string[] } {
+    const errors: string[] = [];
+
+    try {
+      const records = this.fetchRecords(repo.url);
+      this.cache.addRecords(repo.name, records);
+      return { synced: records.length, errors };
+    } catch (e) {
+      const error = e instanceof Error ? e.message : String(e);
+      errors.push(`Failed to sync ${repo.name}: ${error}`);
+      return { synced: 0, errors };
+    }
+  }
+
+  syncMultiple(repos: RemoteRepo[]): void {
+    let totalSynced = 0;
+    let totalErrors = 0;
+
+    for (const repo of repos) {
+      console.log(`Syncing ${repo.name}...`);
+      const result = this.syncRepo(repo);
+      totalSynced += result.synced;
+      totalErrors += result.errors.length;
+      if (result.errors.length > 0) {
+        result.errors.forEach((e) => console.error(`  ⚠️  ${e}`));
+      } else {
+        console.log(`  ✓ ${result.synced} records`);
+      }
+    }
+
+    console.log(
+      `\nSync complete: ${totalSynced} records, ${totalErrors} errors`
+    );
+  }
+
+  private fetchRecords(repoUrl: string): RecordRow[] {
+    // Get all commit hashes and subjects
+    const refs = this.getAllCommitRefs(repoUrl);
+    const records: RecordRow[] = [];
+
+    for (const ref of refs) {
+      try {
+        const trailers = this.extractTrailers(repoUrl, ref);
+        for (const trailer of trailers) {
+          records.push({
+            recordId: this.extractRecordId(trailer),
+            sha: ref,
+            path: "", // Trailers apply to whole commit, not specific path
+            trailer,
+          });
+        }
+      } catch {
+        // Individual commit parsing failed, continue
+        continue;
+      }
+    }
+
+    return records;
+  }
+
+  private getAllCommitRefs(repoUrl: string): string[] {
+    try {
+      const output = execSync(`git ls-remote --heads --tags ${repoUrl}`, {
+        encoding: "utf-8",
+        stdio: ["pipe", "pipe", "ignore"],
+      });
+
+      return output
+        .split("\n")
+        .filter((line) => line.trim())
+        .map((line) => line.split(/\s+/)[0])
+        .filter((sha, index, arr) => arr.indexOf(sha) === index); // Deduplicate
+    } catch {
+      return [];
+    }
+  }
+
+  private extractTrailers(repoUrl: string, sha: string): string[] {
+    try {
+      const output = execSync(`git show ${sha}:`, { encoding: "utf-8", cwd: repoUrl });
+      return output.split("\n").filter((line) => this.isTrailerLine(line));
+    } catch {
+      // For remote URLs, use a temporary shallow clone approach
+      return this.extractTrailersRemote(repoUrl, sha);
+    }
+  }
+
+  private extractTrailersRemote(repoUrl: string, sha: string): string[] {
+    try {
+      // Use git show without needing a clone
+      const output = execSync(`git show ${sha} --format=%B`, {
+        encoding: "utf-8",
+        stdio: ["pipe", "pipe", "ignore"],
+      });
+
+      // Extract only the trailer section (after blank line at end)
+      const lines = output.split("\n");
+      const trailers: string[] = [];
+      let inTrailers = false;
+
+      for (let i = lines.length - 1; i >= 0; i--) {
+        const line = lines[i];
+        if (line.match(/^[A-Z][a-zA-Z0-9-]*:/)) {
+          inTrailers = true;
+          if (line.includes("CommitLore-")) {
+            trailers.push(line);
+          }
+        } else if (inTrailers && line.trim() === "") {
+          break;
+        }
+      }
+
+      return trailers.reverse();
+    } catch {
+      return [];
+    }
+  }
+
+  private isTrailerLine(line: string): boolean {
+    return /^[A-Z][a-zA-Z0-9-]*:/.test(line) && line.includes("CommitLore-");
+  }
+
+  private extractRecordId(trailer: string): string {
+    // Extract from "Record-Id: r-abc123" format
+    const match = trailer.match(/Record-Id:\s*([^\s]+)/);
+    return match ? match[1] : "unknown";
+  }
+}
